//! ARM64 (aarch64) SMP implementation using the GICv3 interrupt controller.
//!
//! Implements `SmpArch` for ARM64 by programming the GIC (Generic Interrupt
//! Controller) v3 distributor to send Software Generated Interrupts (SGIs),
//! acknowledging IPIs via the CPU-interface system registers, and booting
//! Application Processors through PSCI (Power State Coordination Interface).
//!
//! # SMP mechanism overview
//!
//! - **IPI send**: An SGI (Software Generated Interrupt) is generated by
//!   writing the GICD_SGIR register in the distributor. The target CPU is
//!   selected by a CPU target list. We use SGI 0 as the schedule IPI.
//! - **IPI acknowledge**: The CPU interface exposes the active interrupt
//!   through ICC_IAR1_EL1 (Interrupt Acknowledge Register). Reading it
//!   drops the priority and returns the INTID; writing the same INTID to
//!   ICC_EOIR1_EL1 (End Of Interrupt Register) completes handling.
//! - **CPU halt**: The `wfi` (Wait For Interrupt) instruction suspends
//!   execution until an interrupt arrives.
//! - **AP boot**: PSCI `CPU_ON` (SMC64/HVC64 function ID 0xC4000003) is
//!   invoked via `hvc #0` (default conduit; `set_psci_conduit_smc` switches to
//!   `smc`) to power on a secondary CPU at a given entry point. The 64-bit form
//!   keeps the full entry address (the older 0x84000003 SMC32 form
//!   truncated it — see `PSCI_CPU_ON_64`).
//!
//! # Anti-translate vs C
//!
//! Minix3's C SMP layer (arch/i386/smp.c) dispatches architecture operations
//! through global function pointers (`arch_send_smp_schedule_ipi`,
//! `arch_smp_halt_cpu`, `ipi_ack`) that are patched in during `arch_init`.
//! This Rust backend anti-translates that design: instead of indirect calls
//! through global state, each operation talks directly to the hardware via
//! system-register accesses (`mrs`/`msr` for the GIC CPU interface) and a
//! single MMIO write (GICD_SGIR). The only piece of boot-time data retained
//! is the GIC distributor base address — a value, not a function pointer —
//! stored in a per-arch static (see `16-smp.md` §3 D7). This keeps the IPI
//! hot path a direct MMIO store / system-register sequence with no indirect
//! call.
//!
//! C: arch/earm/smp.c — ARM EABI equivalent of arch/i386/smp.c (the
//!    aarch64-specific smp.c may not exist in Minix3; this is the
//!    architecture equivalent of arch/i386/smp.c).

use crate::smp::SmpArch;
use core::sync::atomic::{AtomicU32, Ordering as AtomicOrdering};

/// Hardware Aff0 → logical CPU id map.
///
/// `ap_cpu_id_readback` must be callable from any hot path without touching
/// the platform descriptor. The map is written once per CPU during bring-up
/// (BSP in `smp_init`, each AP in its tail). A sentinel entry means "not
/// recorded yet"; the readback then falls back to Aff0 itself, which is the
/// QEMU single-cluster layout (logical index == Aff0) and the existing
/// behaviour before this map existed.
const CPU_ID_MAP_LEN: usize = 64;
static CPU_ID_MAP: [AtomicU32; CPU_ID_MAP_LEN] =
    [const { AtomicU32::new(u32::MAX) }; CPU_ID_MAP_LEN];

/// Record the logical id for a hardware Aff0. Called on the CPU itself
/// before it enters any kernel path that calls `current_cpu_id()`.
pub fn set_cpu_id(hw_id: u32, logical_id: u32) {
    if let Some(slot) = CPU_ID_MAP.get(hw_id as usize) {
        slot.store(logical_id, AtomicOrdering::Release);
    }
}

/// This CPU's logical id: `MPIDR_EL1.Aff0` through the map, with the
/// unmapped fallback described on [`CPU_ID_MAP`].
pub fn cpu_id_readback() -> u64 {
    let mpidr: u64;
    // SAFETY: MPIDR_EL1 is readable at EL1; the read is side-effect-free.
    unsafe { core::arch::asm!("mrs {}, mpidr_el1", out(reg) mpidr) };
    let aff0 = (mpidr & 0xff) as u32;
    match CPU_ID_MAP.get(aff0 as usize) {
        Some(slot) => {
            let mapped = slot.load(AtomicOrdering::Acquire);
            if mapped == u32::MAX { u64::from(aff0) } else { u64::from(mapped) }
        }
        None => u64::from(aff0),
    }
}

/// GICD_SGIR register offset from the GIC distributor base address.
///
/// Writing this register generates a Software Generated Interrupt (SGI).
/// ARM GIC Architecture Specification §4.3.22 (GICD_SGIR).
const GICD_SGIR: usize = 0xF00;

/// GICD_SGIR target list filter: send to the CPU(s) specified in the CPU
/// target list field (bits [23:16]). Value 0b00 in bits [25:24]. ARM GIC
/// Architecture Specification §4.3.22.
const SGIR_TARGET_LIST_FILTER: u32 = 0 << 24;

/// SGI INTID used for the schedule IPI. SGIs occupy INTID range 0..15;
/// we use ID 0. ARM GIC Architecture Specification §4.3.22.
pub const SCHED_SGI_INTID: u32 = 0;

/// GICD_CTLR offset and its `ARE_NS` bit (GICv3 affinity routing enable).
///
/// `GICD_SGIR` is a GICv2 register: in GICv3 it is only honored when
/// affinity routing is disabled. With `ARE_NS = 1` the send path must use
/// `ICC_SGI1R_EL1`. The distributor's `CTLR` is read at send time because
/// firmware (or a later boot stage) owns the ARE bits.
const GICD_CTLR: usize = 0x0000;
const GICD_CTLR_ARE_NS: u32 = 1 << 4;

/// `ICC_SGI1R_EL1` field positions (ARM GICv3 architecture).
///
/// TargetList selects the destination PEs by Aff0 within the affinity
/// group named by Aff1/Aff2/Aff3; INTID is the SGI number. The current
/// send API carries only the logical CPU index, so this implementation
/// keeps the existing single-cluster assumption: the target's Aff0 is that
/// index and Aff1/2/3 are this CPU's (all CPUs in one cluster). Cross-
/// cluster routing needs a per-CPU MPIDR table and is a recorded
/// follow-up.
const SGI1R_TARGET_LIST_SHIFT: u64 = 0;
const SGI1R_AFFINITY_1_SHIFT: u64 = 16;
const SGI1R_INTID_SHIFT: u64 = 24;
const SGI1R_AFFINITY_2_SHIFT: u64 = 32;
const SGI1R_AFFINITY_3_SHIFT: u64 = 48;

/// Read this CPU's MPIDR affinity fields `(Aff1, Aff2, Aff3)`.
fn mpidr_affinity() -> (u64, u64, u64) {
    let mpidr: u64;
    // SAFETY: MPIDR_EL1 is readable at EL1 (and EL0 with UAO); the read is
    // side-effect-free.
    unsafe { core::arch::asm!("mrs {}, mpidr_el1", out(reg) mpidr) };
    ((mpidr >> 8) & 0xff, (mpidr >> 16) & 0xff, (mpidr >> 32) & 0xff)
}

/// Whether the distributor currently has affinity routing enabled.
fn gicd_are_ns() -> bool {
    // SAFETY: GICD_CTLR is a read-only observation here; the base was set
    // by `set_gicd_base` before any IPI sender can run.
    let ctlr = unsafe {
        core::ptr::read_volatile((gicd_base() + GICD_CTLR) as *const u32)
    };
    ctlr & GICD_CTLR_ARE_NS != 0
}

/// Send the scheduler SGI through `ICC_SGI1R_EL1` (GICv3 ARE mode).
fn send_sgi1r(cpu: u32) {
    let (aff1, aff2, aff3) = mpidr_affinity();
    let target_list = 1u64 << (cpu & 0xF);
    let value = (target_list << SGI1R_TARGET_LIST_SHIFT)
        | (aff1 << SGI1R_AFFINITY_1_SHIFT)
        | ((SCHED_SGI_INTID as u64) << SGI1R_INTID_SHIFT)
        | (aff2 << SGI1R_AFFINITY_2_SHIFT)
        | (aff3 << SGI1R_AFFINITY_3_SHIFT);
    // SAFETY: ICC_SGI1R_EL1 is the architectural GICv3 SGI-generation
    // register; ICC_SRE_EL1.SRE was enabled during interrupt-controller
    // init. The write is side-effecting and has no memory operand.
    unsafe { core::arch::asm!("msr icc_sgi1r_el1, {}", in(reg) value) };
}

/// PSCI `CPU_ON` function ID, **SMC64/HVC64 calling convention**
/// (0xC400_0003; ARM DEN 0022D (PSCI) §5.4.3).
///
/// This used to be the SMC32/HVC32 form (0x8400_0003). Under the
/// 32-bit convention the firmware reads the entry address and context as
/// *w2/w3* — upper 32 bits of x2/x3 are zeroed — which truncates any entry
/// above 4 GiB. The kernel image is linked at 0x1400_0000+ (>4 GiB), so
/// the AP would start at a garbage physical address. The 64-bit form keeps
/// the full x2/x3 widths; arguments are identical otherwise.
const PSCI_CPU_ON_64: u64 = 0xC400_0003;

/// PSCI conduit selection: `false` = hvc (default, direct-kernel boot), `true`
/// = smc (firmware boot: pflash/TF-A resident at EL3). The kernel wiring sets
/// it from DTB `/psci/method` before `boot_ap`; the hvc default preserves "the
/// old behavior when no DTB sets it".
static PSCI_CONDUIT_SMC: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);

/// Set the PSCI conduit from the wiring side (`true` = smc). Must be called
/// before any `boot_ap`.
pub fn set_psci_conduit_smc(smc: bool) {
    PSCI_CONDUIT_SMC.store(smc, core::sync::atomic::Ordering::Release);
}

/// GIC distributor base address, populated during `arch_init`.
///
/// This is the only mutable global in the ARM64 SMP backend: the GIC
/// distributor MMIO base **as reached at runtime**. That is not the
/// raw physical address but the kernel high-half (TTBR1) MMIO alias produced
/// by [`mmio_translate`] in `set_gicd_base`, so `send_sched_ipi`'s write to
/// GICD_SGIR survives `switch_address_space` (the low-half identity mapping
/// in TTBR0 is flushed by `tlbi alle1is` on the first switch). Unlike the C
/// port's function pointers, this holds a *value* (a base address); all
/// behavior is encoded inline in the trait methods, so the IPI hot path
/// remains a direct MMIO write with no indirect call. See `16-smp.md` §3 D7.
///
/// # Safety invariant
///
/// Must be set to the distributor **physical** base via `set_gicd_base`
/// (which routes it to the high-half alias) before any `send_sched_ipi`
/// call. Until then it is 0 and IPI sends must not be attempted.
static mut GICD_BASE: usize = 0;

/// Record the GIC distributor base address.
///
/// Called from `arch_init` once firmware (TF-A/U-Boot) has provided the GIC
/// descriptor. After this call, `send_sched_ipi` is safe to use.
///
/// Currently wired up by `arch_init` on real hardware; `#[allow(dead_code)]`
/// keeps the linker quiet for host/mock builds that never call it.
///
/// # Safety
///
/// Writes to a `static mut`. The caller must ensure no other CPU is
/// concurrently reading `GICD_BASE` (typically called single-threaded
/// during early boot before APs are released).
#[inline]
#[allow(dead_code)]
pub(crate) unsafe fn set_gicd_base(base: usize) {
    // `base` is the physical GICD base; store the high-half (TTBR1) MMIO alias
    // so `send_sched_ipi`'s GICD_SGIR write stays valid across a root switch
    // (otherwise, after the first root switch, that physical address is cut
    // away from the TTBR0 identity mapping -> synchronous exception). `0` is
    // the "not set" sentinel (see this function's description) and keeps its
    // original value without going through translate (a physical `0` falls
    // outside the window and would trigger a const-assert).
    GICD_BASE = if base == 0 {
        0
    } else {
        minix_platform::arch::aarch64::mmio_translate(base as u64) as usize
    };
}

/// Read the GIC distributor base address.
///
/// # Safety
///
/// Reads a `static mut`. Safe in practice once `arch_init` has populated
/// it; the read itself is non-tearing on aarch64.
#[inline]
unsafe fn gicd_base() -> usize {
    let base = GICD_BASE;
    // A zero base used to turn the first SGI send into a store at 0xF00
    // (GICD_SGIR) or a read at 0 (ARE probe) and a translation-fault panic
    // in the middle of `sched_enqueue_with`. Fail at the wiring point
    // instead: `arch_init` seeds this from the platform descriptor.
    assert!(
        base != 0,
        "aarch64 SGI send before set_gicd_base: arch_init did not seed the \
         GIC distributor base from the platform descriptor"
    );
    base
}

/// ARM64 SMP backend using the GICv3 interrupt controller.
///
/// This is a zero-sized type — the only hardware parameter (the GIC
/// distributor base) lives in the `GICD_BASE` static, and all CPU-interface
/// state is reached through system registers.
///
/// C: arch/earm/smp.c (architecture equivalent of arch/i386/smp.c)
pub struct AArch64SmpArch;

impl SmpArch for AArch64SmpArch {
    #[inline]
    fn send_sched_ipi(cpu: u32) {
        // C: arch_send_smp_schedule_ipi(cpu) — smp.c:65
        //
        // GICv3 with affinity routing enabled (ARE_NS=1) ignores the legacy
        // GICD_SGIR path; use ICC_SGI1R_EL1 there. Only when firmware left
        // affinity routing off does the GICv2-compatible distributor
        // register below apply.
        if gicd_are_ns() {
            send_sgi1r(cpu);
            return;
        }

        // Legacy (ARE_NS=0) GICD_SGIR path: generate SGI 0 targeting a
        // single CPU. GICD_SGIR layout (ARM GIC Architecture
        // Specification §4.3.22):
        //   Bits [25:24]: Target List Filter — 0 = send to the CPU(s)
        //                 specified in the CPU target list.
        //   Bits [23:16]: CPU Target List — one bit per CPU in the
        //                 affinity 0 cluster (bit n = CPU n). The field is
        //                 8 bits wide, so this targets CPUs 0..7 (single-
        //                 cluster simplification; GICv3 ARE mode would use
        //                 ICC_SGI0R_EL1 for full affinity routing).
        //   Bits [3:0]:   SGI INTID (0..15). We use 0 for schedule IPI.
        //
        // The CPU id is masked to 3 bits to stay within the 8-bit target
        // list and to keep the shift in range (no undefined shift).
        let target_list = 1u32 << (cpu & 0x07);
        let sgir = SGIR_TARGET_LIST_FILTER | (target_list << 16) | (SCHED_SGI_INTID & 0x0F);

        // SAFETY: `gicd_base()` reads the distributor base set by
        // `arch_init` via `set_gicd_base`. Writing GICD_SGIR is a
        // side-effecting MMIO store that raises an SGI on the target CPU;
        // `write_volatile` prevents the compiler from eliding it. The
        // address is a valid MMIO region once `set_gicd_base` has run.
        unsafe {
            let addr = (gicd_base() + GICD_SGIR) as *mut u32;
            core::ptr::write_volatile(addr, sgir);
        }
    }

    #[inline]
    fn halt_cpu() {
        // C: arch_smp_halt_cpu() — smp.c:60
        //
        // `wfi` (Wait For Interrupt) suspends execution until an interrupt
        // (or debug event) arrives. ARM ARM §C6.2.
        //
        // SAFETY: `wfi` is a hint instruction; it never faults. Safe in
        // kernel mode with interrupts enabled (otherwise it may spin
        // indefinitely). `nomem`/`nostack` mirror the x86_64 `hlt` usage.
        unsafe {
            core::arch::asm!("wfi", options(nomem, nostack));
        }
    }

    fn idle_halt() {
        // C: halt_cpu() — klib.S:407-414 (idle-loop variant: `sti; hlt`).
        //
        // aarch64 equivalent: unmask IRQs (`daifclr, #2` clears the I mask
        // — DAIF I-bit, ARM ARM §D1.12) then `wfi`. As on x86_64, the mask
        // must be cleared before waiting or the CPU never wakes. `wfi`
        // returns when any pending interrupt is taken (the IRQ entry then
        // runs with interrupts masked by hardware PSTATE masking).
        //
        // SAFETY: `msr daifclr` and `wfi` are privileged but confined:
        // the first only unmasks IRQs, the second only sleeps the CPU.
        // Safe in EL1 kernel mode.
        unsafe {
            core::arch::asm!("msr daifclr, #2", "wfi", options(nomem, nostack));
        }
    }

    #[inline]
    fn ack_ipi() {
        // C: ipi_ack() — smp.c:58,198
        //
        // GICv3 interrupt acknowledgement is a two-step system-register
        // dance (ARM GIC Architecture Specification §4.3.7, §4.3.8):
        //   1. Read ICC_IAR1_EL1 — atomically drops the priority of the
        //      current interrupt and returns its INTID.
        //   2. Write that INTID to ICC_EOIR1_EL1 — signals end of
        //      interrupt, allowing re-entrancy of the same INTID.
        //
        // The `SmpArch::ack_ipi` contract has no return value, so the
        // INTID read here is consumed locally and written straight back to
        // ICC_EOIR1_EL1. This is the simplified acknowledgement used on the
        // IPI path: the actual dispatch already happened in the trap
        // handler before this is called.
        let intid: u64;
        // SAFETY: Both instructions are emitted in one asm block so the
        // IAR read is guaranteed to precede the EOIR write. `mrs` reads
        // ICC_IAR1_EL1 (priority drop + INTID return) and `msr` writes the
        // same INTID to ICC_EOIR1_EL1. These are the standard
        // interrupt-acknowledge system-register accesses at EL1; they do
        // not touch Rust memory, and `nostack` holds because no stack
        // access is involved.
        unsafe {
            core::arch::asm!(
                "mrs {intid}, icc_iar1_el1",
                "msr icc_eoir1_el1, {intid}",
                intid = out(reg) intid,
                options(nostack),
            );
        }
        // Intentionally unused: the INTID is consumed by the EOIR write
        // above; nothing else needs it under the simplified ack contract.
        let _ = intid;
    }

    #[inline]
    fn boot_ap(cpu: u32, entry: usize) {
        // C: AP boot protocol — arch/i386/smp.c (architecture equivalent)
        //
        // ARM64 secondary CPUs are powered on by firmware through PSCI
        // (Power State Coordination Interface, ARM DEN 0022D). We issue the
        // SMC64 `CPU_ON` call via `hvc #0` (hypervisor conduit) — the SMC64
        // form keeps the full 64-bit entry address (see PSCI_CPU_ON_64 for
        // the truncation rationale).
        //
        // PSCI CPU_ON parameters (SMC64/HVC64 calling convention):
        //   x0 = function ID  (0xC4000003)
        //   x1 = target_cpu   (MPIDR-based affinity of the secondary CPU)
        //   x2 = entry_point  (physical address of AP early stub)
        //   x3 = context_id   (opaque cookie delivered to the AP in x0 —
        //        §3.1: carries the bootstrap pointer so the stub can find
        //        its record without relative-address arithmetic)
        // On success x0 = 0 (PSCI_SUCCESS); a non-zero value is an error.
        //
        // We use the linear CPU id as the MPIDR target. Real MPIDR encoding
        // uses affinity fields (Aff0..Aff3); a production port would
        // translate cpu -> MPIDR via a per-platform table. This
        // simplification matches the single-cluster boot model.
        let fid = PSCI_CPU_ON_64;
        let target_cpu = cpu as u64;
        let entry_point = entry as u64;
        // §3.1: the AP receives this in x0 — the bootstrap pointer (the
        // stub sits inside the kernel image and reads its record relative
        // to known image addresses, but handing the entry cookie through
        // keeps the channel open for record-at-any-address layouts).
        let context_id: u64 = entry as u64;
        let ret: u64;

        // SAFETY: `hvc #0` traps to the hypervisor/firmware PSCI handler.
        // All argument registers (x0..x3) are explicitly initialized. The
        // call is side-effecting (powers on another CPU) and may
        // synchronize with the incoming AP, so `nomem` is deliberately not
        // set; `nostack` is set because hvc does not access the stack. x0
        // carries the PSCI return code.
        // The conduit is chosen from DTB `/psci/method` (the kernel wiring sets
        // it through `set_psci_conduit_smc`; Linux reads the FDT the same way).
        // Both states are empirically established: on the firmware boot chain
        // hvc is silently swallowed (ret=0 fake success, no AP ever appears);
        // smc issued at the wrong level bounces back as an unclassified
        // exception. Hard-coding either one only works for one boot chain.
        if PSCI_CONDUIT_SMC.load(core::sync::atomic::Ordering::Acquire) {
            unsafe {
                core::arch::asm!(
                    "smc #0",
                    inout("x0") fid => ret,
                    in("x1") target_cpu,
                    in("x2") entry_point,
                    in("x3") context_id,
                    options(nostack),
                );
            }
        } else {
            unsafe {
                core::arch::asm!(
                    "hvc #0",
                    inout("x0") fid => ret,
                    in("x1") target_cpu,
                    in("x2") entry_point,
                    in("x3") context_id,
                    options(nostack),
                );
            }
        }
        // Non-zero return indicates a PSCI error (e.g. already_on,
        // invalid_params). We do not propagate it: the trait contract is
        // best-effort fire-and-forget, mirroring the C port.
        // Receipt diagnostics (removed after use; same shape as riscv sbi-hs):
        // without recording the CPU_ON result, an AP that never arrives cannot
        // be split into "firmware refused" vs "the stub died"; recording the
        // arguments on the same line guards against static-undetectable errors
        // like "we passed the wrong entry".
        let _ = ret;
        {
            use minix_plat::{CurrentEarlyConsole as Console, EarlyConsole as _};
            Console::write_str("nk4c: psci-on ret=");
            let mut hex = [0u8; 16];
            let mut v = ret;
            for byte in hex.iter_mut().rev() {
                *byte = b"0123456789abcdef"[(v & 0xf) as usize];
                v >>= 4;
            }
            Console::write_str(core::str::from_utf8(&hex).unwrap_or("?"));
            Console::write_str("\n");
        }
    }

    fn current_cpu() -> u32 {
        // C: `cpuid` reads from per-CPU kernel stack top.
        // Rust: read MPIDR_EL1 and extract Aff0 (low 8 bits).
        //
        // MPIDR_EL1: bits 0-7 hold Aff0 (CPU ID within a cluster).
        // ARM ARM D7.2.94. In a single-cluster system, Aff0 == logical
        // CPU ID (0, 1, 2, ...).
        //
        // SAFETY: `mrs` reads a system register. MPIDR_EL1 is accessible
        // at all exception levels and has no side effects.
        let mpidr: u64;
        unsafe {
            core::arch::asm!(
                "mrs {0}, mpidr_el1",
                out(reg) mpidr,
                options(nomem, nostack),
            );
        }
        (mpidr & 0xFF) as u32
    }
}
